findings.suggested_fix:
Add a generation ref next to `timer`, bump it at the top of `run()` and in the unmount cleanup, and bail out of every async continuation whose generation is stale:

const gen = useRef(0);
const stopPolling = () => { gen.current += 1; if (timer.current) { clearTimeout(timer.current); timer.current = null; } };
useEffect(() => stopPolling, []);

// in run(), after `const my = ++gen.current;`
const accepted = await reportBuilderApi.execute(selected, {...});
if (gen.current !== my) return;
setTaskId(accepted.task_id); setPhase('polling'); poll(accepted.task_id, my);

// in poll(), check the token both before scheduling and first thing inside the callback
const poll = (id: string, my: number) => {
  if (gen.current !== my) return;
  if (Date.now() - startedAt.current > POLL_TIMEOUT_MS) { setPhase('timeout'); stopPolling(); return; }
  timer.current = setTimeout(() => {
    void (async () => {
      try {
        const st = await reportBuilderApi.executionStatus(id);
        if (gen.current !== my) return;
        ...
      } catch (err) {
        if (gen.current !== my) return;
        ...
      }
      poll(id, my);
    })();
  }, POLL_INTERVAL_MS);
};

